function validate([nums]) {
  if (nums.length < 1 || nums.length > 1500) return 'nums needs 1 to 1500 values.';
  if (nums.some(v => v < 1 || v > 1500)) return 'Each value in nums is between 1 and 1500.';
  return null;
}

