function uniqueXorTriplets(nums) {
  const values = [...new Set(nums)];
  const largest = Math.max(...values);
  let size = 1;
  while (size <= largest) {
    size *= 2;
  }
  const pairs = new Array(size).fill(false);
  for (let a = 0; a < values.length; a++) {
    for (let b = a; b < values.length; b++) {
      pairs[values[a] ^ values[b]] = true;
    }
  }
  const triplets = new Array(size).fill(false);
  for (let pair = 0; pair < size; pair++) {
    if (!pairs[pair]) {
      continue;
    }
    for (const value of values) {
      triplets[pair ^ value] = true;
    }
  }
  return triplets.filter(Boolean).length;
}

