function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  if (size === 'large') {
    if (rand() < 0.3) {
      // Every value from 1 to 1500 once, shuffled: the most distinct values possible.
      const nums = Array.from({ length: 1500 }, (_, i) => i + 1);
      for (let i = nums.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [nums[i], nums[j]] = [nums[j], nums[i]];
      }
      return [nums];
    }
    // A random range of values, sometimes all multiples of a power of two, so the answers differ.
    const step = pick([1, 1, 2, 8, 64]);
    const low = pick([1, 1, 700, 1400]);
    const nums = Array.from({ length: 1500 }, () => {
      const value = low + Math.floor(rand() * (1501 - low));
      return Math.max(step, value - value % step);
    });
    return [nums];
  }
  const n = 1 + Math.floor(rand() * 10);
  const top = pick([1, 3, 8, 20, 100, 1500]);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
